package glitch

import data.glitch_lib

# Define the suspicious comment keywords and security-related phrases
suspicious_keywords := {"BUG", "HACK", "FIXME", "LATER", "LATER2", "TODO", "XXX", "TEMP", "DEBUG", "NOTE", "WORKAROUND"}
security_phrases := {"bypass", "hard-coded credential", "missing validation", "insecure default", "disable security", "placeholder", "dummy"}

# Check if a comment contains suspicious keywords or security phrases
is_suspicious_comment(comment) {
    # Check for explicit flags (case-insensitive)
    regex.match(sprintf("(?i).*\\b(%s)\\b", [concat("|", suspicious_keywords)]), comment.content)
} else {
    # Check for security-related phrases (case-insensitive)
    regex.match(sprintf("(?i).*%s", [concat("|", security_phrases)]), comment.content)
}

